			ret

;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			pop hl
			jr z, ntc_ftov_t
			ld (hl), 0
			inc hl
			ld (hl), 0
			ret
ntc_ftov_t:
			ld (hl), #ff
			inc hl
			ld (hl), #ff
			ret

; ============================================================
; Arithmetic
; ============================================================

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ex de, hl
			or a
			sbc hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_2x
;kw_2x, <var>, <destvar>
kw_2x:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvl ntc_mul
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop de
			jp ntc_mul

;## ntc_div ntc_data
; HL / DE signed, truncating. (ntc_mode) 0 = quotient, 1 = remainder.
; Remainder takes the dividend's sign. Divide by zero gives
; quotient 0, remainder = dividend. Pops destvar and stores.
ntc_div:
			ld a, d
			or e
			jr nz, ntc_div_nz
			ld a, (ntc_mode)
			or a
			jr nz, ntc_div_store
			ld hl, 0
			jr ntc_div_store
ntc_div_nz:
			ld a, h
			ld (ntc_sgnr), a
			xor d
			ld (ntc_sgnq), a
			bit 7, h
			jr z, ntc_div_hpos
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_hpos:
			bit 7, d
			jr z, ntc_div_dpos
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_div_dpos:
			ld a, h
			ld c, l
			ld hl, 0
			ld b, 16
ntc_div_loop:
			sla c
			rla
			adc hl, hl
			sbc hl, de
			jr nc, ntc_div_one
			add hl, de
			djnz ntc_div_loop
			jr ntc_div_done
ntc_div_one:
			inc c
			djnz ntc_div_loop
ntc_div_done:
			ld b, a
			ld a, (ntc_mode)
			or a
			jr z, ntc_div_q
			ld a, (ntc_sgnr)
			jr ntc_div_sign
ntc_div_q:
			ld h, b
			ld l, c
			ld a, (ntc_sgnq)
ntc_div_sign:
			rla
			jr nc, ntc_div_store
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_store:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_divvl ntc_div
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			xor a
			ld (ntc_mode), a
ntc_divvl:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			pop de
			jp ntc_div

;## kw_andvv
;kw_andvv, <var1>, <var2>, <destvar>
kw_andvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			and e
			ld e, a
			inc hl
			ld a, (hl)
			and d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_andvl
;kw_andvl, <var>, <literal>, <destvar>
kw_andvl:
			pop hl
			pop de
			ld a, (hl)
			and e
			ld e, a
			inc hl
			ld a, (hl)
			and d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_orvv
;kw_orvv, <var1>, <var2>, <destvar>
kw_orvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			or e
			ld e, a
			inc hl
			ld a, (hl)
			or d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scplevl ntc_cmp
kw_scplevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sle

;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sgt

;## kw_scpgevl ntc_cmp
kw_scpgevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sge

;## kw_cpeqvl ntc_cmp
kw_cpeqvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_eq

;## kw_vptrtov8
;kw_vptrtov8, <addrvar>, <destvar>  - PEEK(var)
kw_vptrtov8:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld a, (de)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_ltolptr8
;kw_ltolptr8, <literal>, <literaladdr>  - POKE literal, literal
kw_ltolptr8:
			pop bc
			pop hl
			ld (hl), c
			ret

;## kw_vtolptr8
;kw_vtolptr8, <sourcevar>, <literaladdr>  - POKE literal, var
kw_vtolptr8:
			pop hl
			ld c, (hl)
			pop hl
			ld (hl), c
			ret

;## kw_aget8
;kw_aget8, <arraybase>, <indexvar>, <destvar>  - Byte array element (0 .. 255)
kw_aget8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_aset8
;kw_aset8, <arraybase>, <indexvar>, <sourcevar>  - set a Byte array element (low byte)
kw_aset8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld a, (hl)
			ld (de), a
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## kw_strcmpne
;kw_strcmpne, <addr1>, <addr2>  - Z if not equal
kw_strcmpne:
			pop de
			pop hl
ntc_strne_loop:
			ld a, (de)
			cp (hl)
			jr nz, ntc_strne_t
			or a
			jr z, ntc_strne_f
			inc hl
			inc de
			jr ntc_strne_loop
ntc_strne_t:
			xor a
			ret
ntc_strne_f:
			inc a
			ret

; ============================================================
; I/O - no firmware, no call, no push. SP stays in the thread.
; Shared routines are entered with jp and the return address in
; IX, and end with jp (ix). Keywords that are done use
; ld ix, ntc_next (a ret) so the routine continues the thread.
; ============================================================

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			pop de
			pop hl
ntc_uc_loop:
			ld a, (hl)
			cp 'a'
			jr c, ntc_uc_put
			cp 'z' + 1
			jr nc, ntc_uc_put
			sub 32
ntc_uc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_uc_loop

;## kw_strrtrim ntc_data
;kw_strrtrim, <dest>, <src>  - RTrim$
kw_strrtrim:
			pop de
			pop hl
			ld (ntc_sptr), de
ntc_rt_copy:
			ld a, (hl)
			ld (de), a
			or a
			jr z, ntc_rt_back
			inc hl
			inc de
			jr ntc_rt_copy
ntc_rt_back:
			ld hl, (ntc_sptr)
			ex de, hl
ntc_rt_loop:
			or a
			sbc hl, de
			add hl, de
			ret z
			dec hl
			ld a, (hl)
			cp ' '
			ret nz
			ld (hl), 0
			jr ntc_rt_loop

;## kw_strtrim kw_strrtrim
;kw_strtrim, <dest>, <src>  - Trim$
kw_strtrim:
			pop de
			pop hl
ntc_tr_skip:
			ld a, (hl)
			cp ' '
			jr nz, ntc_tr_go
			inc hl
			jr ntc_tr_skip
ntc_tr_go:
			ld (ntc_sptr), de
			jp ntc_rt_copy

;## ntc_capfind ntc_data
; ntc_capfind - the body of a class's Capability(name) keyword.
;   HL = the name asked for (0 ended), DE = the result's address,
;   BC = the class's table: name (capitals, 0 ended), dw value, ..., db 0.
; The name is matched without regard to case. Found: the value, Z set (true).
; Not found: 0, NZ. Runs on the thread: no call, no push.
ntc_capfind:
			ld (ntc_capres), de
			ld (ntc_capname), hl
ntc_cf_entry:
			ld a, (bc)
			or a
			jr z, ntc_cf_none
			ld hl, (ntc_capname)
ntc_cf_cmp:
			ld a, (hl)
			cp 'a'
			jr c, ntc_cf_up
			cp 'z' + 1
			jr nc, ntc_cf_up
			sub 32
ntc_cf_up:
			ld e, a
			ld a, (bc)
			cp e
			jr nz, ntc_cf_skip
			or a
			jr z, ntc_cf_found
			inc hl
			inc bc
			jr ntc_cf_cmp
ntc_cf_skip:
			ld a, (bc)			; the rest of this name, its 0 and its value
			inc bc
			or a
			jr nz, ntc_cf_skip
			inc bc
			inc bc
			jr ntc_cf_entry
ntc_cf_found:
			inc bc
			ld a, (bc)
			ld e, a
			inc bc
			ld a, (bc)
			ld d, a
			ld hl, (ntc_capres)
			ld (hl), e
			inc hl
			ld (hl), d
			xor a				; Z: found
			ret
ntc_cf_none:
			ld hl, (ntc_capres)
			ld (hl), a
			inc hl
			ld (hl), a
			inc a				; NZ: not found
			ret
ntc_capres:		dw 0
ntc_capname:	dw 0

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; not used (a stream has no rows)
ntc_scols:		db 80			; columns
ntc_bdosa:		db 0			; ntc_bdos: A on return
ntc_smode:		db 2			; screen mode (Graphics on an Amstrad CPC: CP/M's console is mode 2)
ntc_cpmtop:		dw #FFFF		; the heap's top if lower than the BDOS (Graphics on CP/M Plus: GFH_AT)
				ds 256			; the program's real stack
ntc_cpmstack:

;## ntc_plat_bdos ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_bdos - C = BDOS function, DE = argument. A (also in ntc_bdosa)
; and HL come back. IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_bdos:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call 5
			di
			ld sp, (ntc_ip)
			ld (ntc_bdosa), a
			ld ix, (ntc_hostix)
			jp (ix)

;## ntc_plat_screen ntc_plat_bdos ntc_plat_data ntc_data
; ntc_plat_putc - A = character: BDOS 6, count the column
ntc_plat_putc:
			ld e, a
			ld c, 6
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_bdos
ntc_pc_back:
			ld ix, (ntc_pclink)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; the terminal wrapped
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - CR LF
ntc_plat_newline:
			ld (ntc_pclink), ix
			ld e, 13
			ld c, 6
			ld ix, ntc_nl_lf
			jp ntc_bdos
ntc_nl_lf:
			ld e, 10
			ld c, 6
			ld ix, ntc_nl_done
			jp ntc_bdos
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld ix, (ntc_pclink)
			jp (ix)

ntc_pclink:		dw 0

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - warm boot back to CP/M
ntc_plat_exit:
			jp 0

; ============================================================
; File system (FileSystem class) - BDOS files, FCBs, 128 byte records
; ============================================================
; The class's methods are keywords: they take their arguments
; into fs_a1 .. fs_a3, the result's address into fs_res, and
; jump to fs_go with HL = the routine. fs_go runs the routine on
; the real stack (call / push are fine there, as for BDOS), with
; interrupts on, and stores its HL result at fs_res (fs_go4: a
; Long, high word in fs_hi; fs_go0: no store - the routine writes
; the result itself). A routine that fails jumps to fs_err with
; HL = the status (negative); fs_err unwinds to fs_go.
;
; Slots: 0 is for Load / Save / Delete / Exists / Rename / Size,
; 1 and 2 are the handles Open gives. A slot is FS_SLOT bytes:
;   +0  FCB (36)    +36 mode (0 free, 1 read, 2 write, 3 update)
;   +37 position in the buffer (0-128)
;   +38 buffer state (0 not loaded, 1 loaded, 2 changed)
;   +39 record number in the buffer (2)   +42 buffer (128)
; Every record goes through random read / write (BDOS 33 / 34),
; so reading, writing and Seek all work the same way.

FS_SLOT		equ 170
FS_MODE		equ 36
FS_BPOS		equ 37
FS_BST		equ 38
FS_RECL		equ 39
FS_RECH		equ 40
FS_BUF		equ 42
FS_MAXH		equ 2

FS_NOTFOUND	equ -2
FS_FULL		equ -3
FS_BADNAME	equ -4
FS_NOHANDLE	equ -5
FS_BADHANDLE	equ -6
FS_EOF		equ -7
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_EXISTS	equ -10
FS_BADMODE	equ -11

;## ntc_plat_fs ntc_data ntc_capfind @shared
fs_a1:			dw 0
fs_a2:			dw 0
fs_a3:			dw 0
fs_res:			dw 0
fs_hi:			dw 0
fs_sp:			dw 0
fs_esp:			dw 0
fs_six:			dw 0
fs_siy:			dw 0
fs_cnt:			dw 0
fs_rest:		dw 0
fs_ptr:			dw 0
fs_cap:			db 0
fs_store:		db 0			; 0 none, 2 Integer, 4 Long
fs_slots:		ds FS_SLOT * (FS_MAXH + 1)

; fs_go / fs_go4 / fs_go0 - HL = the routine (see above)
fs_go0:
			xor a
			jr fs_gostart
fs_go4:
			ld a, 4
			jr fs_gostart
fs_go:
			ld a, 2
fs_gostart:
			ld (fs_store), a
			ld (fs_sp), sp
			ld sp, (ntc_csp)
			ld (fs_six), ix
			ld (fs_siy), iy
			ld de, 0
			ld (fs_hi), de
			ei
			ld (fs_esp), sp
			call fs_jphl
fs_back:
			di
			ld ix, (fs_six)
			ld iy, (fs_siy)
			ld a, (fs_store)
			or a
			jr z, fs_gone
			ex de, hl
			ld hl, (fs_res)
			ld (hl), e
			inc hl
			ld (hl), d
			cp 4
			jr nz, fs_gone
			ld de, (fs_hi)
			inc hl
			ld (hl), e
			inc hl
			ld (hl), d
fs_gone:
			ld sp, (fs_sp)
			ret
fs_jphl:
			jp (hl)

; fs_err - HL = status: back to fs_go with it (a Long result gets -1 high)
fs_err:
			ld sp, (fs_esp)
			ld de, #FFFF
			ld (fs_hi), de
			jr fs_back

; fs_slotix - A = slot number: IX = the slot
fs_slotix:
			ld ix, fs_slots
			ld de, FS_SLOT
			or a
			ret z
fs_si_lp:
			add ix, de
			dec a
			jr nz, fs_si_lp
			ret

; fs_handle - HL = a handle from the program: IX = its slot (open), else fs_err
fs_handle:
			ld a, h
			or a
			jr nz, fs_badh
			ld a, l
			or a
			jr z, fs_badh
			cp FS_MAXH + 1
			jr nc, fs_badh
			call fs_slotix
			ld a, (ix + FS_MODE)
			or a
			ret nz
fs_badh:
			ld hl, FS_BADHANDLE
			jp fs_err

; fs_handlew - as fs_handle, and the file must be open for writing
fs_handlew:
			call fs_handle
			ld a, (ix + FS_MODE)
			cp 1
			ret nz
			ld hl, FS_BADMODE
			jp fs_err

; fs_clear - zero the slot's FCB, buffer state and record number
fs_clear:
			push ix
			pop hl
			ld b, FS_BUF
fs_cl_lp:
			ld (hl), 0
			inc hl
			djnz fs_cl_lp
			ret

; fs_parse - HL = name ("D:NAME.EXT", any case): the name part of the FCB at IX
; (bytes 0-11). A bad name goes to fs_err
fs_parse:
			push ix
			pop de
			xor a
			ld (de), a			; drive: the current one
			inc de
			push de
			ld b, 11
			ld a, ' '
fs_pa_sp:
			ld (de), a
			inc de
			djnz fs_pa_sp
			pop de				; DE = name field
			ld a, (hl)
			or a
			jr z, fs_pa_bad
			inc hl
			ld a, (hl)
			dec hl
			cp ':'
			jr nz, fs_pa_name
			ld a, (hl)
			call fs_upper
			sub 'A' - 1
			jr c, fs_pa_bad
			cp 27				; A-Z: CP/M's are A-P, Q-Z for systems that have more (CyborgOS's Z)
			jr nc, fs_pa_bad
			ld (ix + 0), a
			inc hl
			inc hl
fs_pa_name:
			ld b, 8
			call fs_pa_part
			ld a, (ix + 1)
			cp ' '
			jr z, fs_pa_bad		; no name before the dot / the end
			ld a, (hl)
			or a
			ret z
			cp '.'
			jr nz, fs_pa_bad
			inc hl
			push ix
			pop de
			ld a, 9
			add a, e
			ld e, a
			jr nc, fs_pa_ext
			inc d
fs_pa_ext:
			ld b, 3
			call fs_pa_part
			ld a, (hl)
			or a
			ret z
fs_pa_bad:
			ld hl, FS_BADNAME
			jp fs_err
; one part: up to B characters from HL to DE, stops at '.' or the end
fs_pa_part:
			ld a, (hl)
			or a
			ret z
			cp '.'
			ret z
			call fs_upper
			cp '!'
			jr c, fs_pa_bad
			cp 127
			jr nc, fs_pa_bad
			push hl
			ld hl, fs_pa_badch
			ld c, a
fs_pa_chk:
			ld a, (hl)
			or a
			jr z, fs_pa_ok
			cp c
			jr z, fs_pa_bad2
			inc hl
			jr fs_pa_chk
fs_pa_bad2:
			pop hl
			jr fs_pa_bad
fs_pa_ok:
			pop hl
			ld a, b
			or a
			jr z, fs_pa_bad		; too long
			ld a, c
			ld (de), a
			inc de
			inc hl
			dec b
			jr fs_pa_part
fs_pa_badch:	db "*?:;<>=,[]|", 0

fs_upper:
			cp 'a'
			ret c
			cp 'z' + 1
			ret nc
			sub 32
			ret

; fs_bdos - C = function, DE = argument; IX / IY kept; A = the result
fs_bdos:
			push ix
			push iy
			call 5
			pop iy
			pop ix
			ret
; fs_fcb - C = function on the slot's FCB
fs_fcb:
			push ix
			pop de
			jr fs_bdos
; fs_dma - the slot's buffer is where records go
fs_dma:
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ex de, hl
			ld c, 26
			jr fs_bdos
; fs_bufpos - HL = the buffer at the current position
fs_bufpos:
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ld e, (ix + FS_BPOS)
			ld d, 0
			add hl, de
			ret
; fs_setrec - the record number into the FCB's random record field
fs_setrec:
			ld a, (ix + FS_RECL)
			ld (ix + 33), a
			ld a, (ix + FS_RECH)
			ld (ix + 34), a
			ld (ix + 35), 0
			ret
; fs_rdrec - read the record into the buffer: Z read, NZ none there
fs_rdrec:
			call fs_dma
			call fs_setrec
			ld c, 33
			call fs_fcb
			or a
			ret
; fs_wrrec - write the buffer as the record; a failure goes to fs_err
fs_wrrec:
			call fs_dma
			call fs_setrec
			ld c, 34
			call fs_fcb
			or a
			ret z
			ld hl, FS_FULL
			jp fs_err
; fs_fill - the buffer full of ^Z (CP/M's end of text)
fs_fill:
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ld b, 128
fs_fi_lp:
			ld (hl), 26
			inc hl
			djnz fs_fi_lp
			ret
; fs_flush - a changed buffer goes back to its record
fs_flush:
			ld a, (ix + FS_BST)
			cp 2
			ret nz
			call fs_wrrec
			ld (ix + FS_BST), 1
			ret
; fs_next - on to the next record (the buffer was used up)
fs_next:
			call fs_flush
			inc (ix + FS_RECL)
			jr nz, fs_nx_1
			inc (ix + FS_RECH)
fs_nx_1:
			ld (ix + FS_BPOS), 0
			ld (ix + FS_BST), 0
			ret
; fs_getb - A = the next byte, carry clear; carry set at the end of the file
fs_getb:
			ld a, (ix + FS_BPOS)
			cp 128
			call z, fs_next
			ld a, (ix + FS_BST)
			or a
			jr nz, fs_gb_have
			call fs_rdrec
			scf
			ret nz
			ld (ix + FS_BST), 1
fs_gb_have:
			call fs_bufpos
			ld a, (hl)
			inc (ix + FS_BPOS)
			or a
			ret
; fs_putb - A = the byte to write at the position
fs_putb:
			push af
			ld a, (ix + FS_BPOS)
			cp 128
			call z, fs_next
			ld a, (ix + FS_BST)
			or a
			jr nz, fs_pb_have
			call fs_rdrec			; keep what the record already holds
			call nz, fs_fill		; past the end: a fresh record
			ld (ix + FS_BST), 1
fs_pb_have:
			call fs_bufpos
			pop af
			ld (hl), a
			inc (ix + FS_BPOS)
			ld (ix + FS_BST), 2
			ret
; fs_close - write back what is left, close the file, free the slot
fs_close:
			ld a, (ix + FS_MODE)
			ld (ix + FS_MODE), 0
			cp 1
			jr z, fs_cs_rd
			call fs_flush
fs_cs_rd:
			ld c, 16
			call fs_fcb
			inc a
			ret nz
			ld hl, FS_FAILED
			jp fs_err

; fs_named - slot 0, its FCB set from the name at (fs_a1)
fs_named:
			xor a
			call fs_slotix
			call fs_clear
			ld hl, (fs_a1)
			jp fs_parse
; fs_openit - open the slot's file; not there goes to fs_err
fs_openit:
			ld c, 15
			call fs_fcb
			inc a
			ret nz
			ld hl, FS_NOTFOUND
			jp fs_err
; fs_makeit - a new empty file in place of any old one
fs_makeit:
			ld c, 19
			call fs_fcb			; delete (it need not be there)
			ld (ix + 12), 0
			ld (ix + 14), 0
			ld (ix + 32), 0
			ld c, 22
			call fs_fcb
			inc a
			ret nz
			ld hl, FS_FULL
			jp fs_err

; ---- the routines the methods name ------------------------------

; Load(name, addr, maxlen): the file into memory, at most maxlen bytes.
; Bytes loaded (whole records: CP/M keeps no exact length), or a status.
; More data than maxlen (beyond the last record's padding): FS_TOOBIG.
fs_load:
			call fs_named
			call fs_openit
			ld hl, (fs_a2)
			ld (fs_ptr), hl
			ld hl, (fs_a3)
			ld (fs_rest), hl
			ld hl, 0
			ld (fs_cnt), hl
fs_ld_lp:
			call fs_rdrec
			jr nz, fs_ld_end
			ld hl, (fs_rest)
			ld a, h
			or l
			jr nz, fs_ld_some
			ld hl, FS_TOOBIG
			jp fs_err
fs_ld_some:
			ld bc, 128			; BC = min(128, rest)
			ld a, h
			or a
			jr nz, fs_ld_bc
			ld a, l
			cp 128
			jr nc, fs_ld_bc
			ld c, l
fs_ld_bc:
			or a
			sbc hl, bc
			ld (fs_rest), hl
			ld hl, (fs_cnt)
			add hl, bc
			ld (fs_cnt), hl
			push bc
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ld de, (fs_ptr)
			ldir
			ld (fs_ptr), de
			pop bc
			ld a, c
			cp 128
			jr nz, fs_ld_end		; a part record: maxlen reached
			inc (ix + FS_RECL)
			jr nz, fs_ld_lp
			inc (ix + FS_RECH)
			jr fs_ld_lp
fs_ld_end:
			ld c, 16
			call fs_fcb
			ld hl, (fs_cnt)
			ret

; Save(name, addr, len): a new file holding len bytes (the last record padded with ^Z)
fs_save:
			call fs_named
			call fs_makeit
			ld hl, (fs_a2)
			ld (fs_ptr), hl
			ld hl, (fs_a3)
			ld (fs_rest), hl
fs_sv_lp:
			ld hl, (fs_rest)
			ld a, h
			or l
			jr z, fs_sv_end
			ld bc, 128
			ld a, h
			or a
			jr nz, fs_sv_bc
			ld a, l
			cp 128
			jr nc, fs_sv_bc
			ld c, l
fs_sv_bc:
			or a
			sbc hl, bc
			ld (fs_rest), hl
			push bc
			call fs_fill
			pop bc
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ex de, hl
			ld hl, (fs_ptr)
			ldir
			ld (fs_ptr), hl
			call fs_wrrec
			inc (ix + FS_RECL)
			jr nz, fs_sv_lp
			inc (ix + FS_RECH)
			jr fs_sv_lp
fs_sv_end:
			ld c, 16
			call fs_fcb
			inc a
			ld hl, 0
			ret nz
			ld hl, FS_FAILED
			ret

; Delete(name)
fs_delete:
			call fs_named
			ld c, 19
			call fs_fcb
			inc a
			ld hl, 0
			ret nz
			ld hl, FS_NOTFOUND
			ret

; Exists(name): True (-1) / False (0)
fs_exists:
			call fs_named
			ld c, 15
			call fs_fcb
			inc a
			ld hl, 0
			ret z
			dec hl
			ret

; Rename(old, new) - a file called new already there: FS_EXISTS
fs_rename:
			ld hl, (fs_a1)			; keep the old name
			ld (fs_a3), hl
			ld hl, (fs_a2)
			ld (fs_a1), hl
			call fs_named			; is new there already?
			ld c, 15
			call fs_fcb
			inc a
			ld hl, FS_EXISTS
			jp nz, fs_err
			ld hl, (fs_a3)			; the old name
			ld (fs_a1), hl
			call fs_named
			push ix
			ld de, 16
			add ix, de
			ld hl, (fs_a2)
			call fs_parse			; the new name at FCB + 16
			pop ix
			ld c, 23
			call fs_fcb
			inc a
			ld hl, 0
			ret nz
			ld hl, FS_NOTFOUND
			ret

; Size(name) As Long: bytes (whole records)
fs_size:
			call fs_named
			call fs_openit
			ld c, 35
			call fs_fcb
			ld l, (ix + 33)
			ld h, (ix + 34)
			ld e, (ix + 35)
			ld d, 0
			ld b, 7
fs_sz_lp:
			add hl, hl
			rl e
			rl d
			djnz fs_sz_lp
			ld (fs_hi), de
			ret

; Open(name, mode): a handle (1 or 2), or a status.
; mode 1 read (must be there), 2 write (a new file), 3 update (read and write; made if not there)
fs_open:
			ld a, 1
fs_op_find:
			push af
			call fs_slotix
			pop af
			ld b, a
			ld a, (ix + FS_MODE)
			or a
			jr z, fs_op_got
			ld a, b
			inc a
			cp FS_MAXH + 1
			jr c, fs_op_find
			ld hl, FS_NOHANDLE
			jp fs_err
fs_op_got:
			ld a, b
			ld (fs_cap), a			; the handle
			call fs_clear
			ld hl, (fs_a1)
			call fs_parse
			ld a, (fs_a2)
			ld hl, (fs_a2)
			ld e, a
			ld a, h
			or a
			jr nz, fs_op_bad
			ld a, e
			cp 4				; ForReadRaw: ForRead (CP/M reads every record anyway)
			jr nz, fs_op_m
			ld a, 1
			ld (fs_a2), a
fs_op_m:
			cp 1
			jr z, fs_op_rd
			cp 2
			jr z, fs_op_wr
			cp 3
			jr z, fs_op_up
fs_op_bad:
			ld hl, FS_BADMODE
			jp fs_err
fs_op_rd:
			call fs_openit
			jr fs_op_done
fs_op_wr:
			call fs_makeit
			jr fs_op_done
fs_op_up:
			ld c, 15
			call fs_fcb
			inc a
			jr nz, fs_op_done
			ld (ix + 12), 0
			ld (ix + 32), 0
			call fs_makeit
fs_op_done:
			ld a, (fs_a2)
			ld (ix + FS_MODE), a
			ld a, (fs_cap)
			ld l, a
			ld h, 0
			ret

; Close(h)
fs_closeh:
			ld hl, (fs_a1)
			call fs_handle
			call fs_close
			ld hl, 0
			ret

; ReadByte(h): 0-255, or FS_EOF
fs_readb:
			ld hl, (fs_a1)
			call fs_handle
			call fs_getb
			ld hl, FS_EOF
			ret c
			ld l, a
			ld h, 0
			ret

; WriteByte(h, b)
fs_writeb:
			ld hl, (fs_a1)
			call fs_handlew
			ld a, (fs_a2)
			call fs_putb
			ld hl, 0
			ret

; Read(h, addr, count): bytes read (fewer at the end of the file)
fs_read:
			ld hl, (fs_a1)
			call fs_handle
			ld hl, 0
			ld (fs_cnt), hl
fs_rd_lp:
			ld hl, (fs_cnt)
			ld de, (fs_a3)
			or a
			sbc hl, de
			jr nc, fs_rd_end
			call fs_getb
			jr c, fs_rd_end
			ld hl, (fs_a2)
			ld de, (fs_cnt)
			add hl, de
			ld (hl), a
			inc de
			ld (fs_cnt), de
			jr fs_rd_lp
fs_rd_end:
			ld hl, (fs_cnt)
			ret

; Write(h, addr, count): count, or a status
fs_write:
			ld hl, (fs_a1)
			call fs_handlew
			ld hl, 0
			ld (fs_cnt), hl
fs_wr_lp:
			ld hl, (fs_cnt)
			ld de, (fs_a3)
			or a
			sbc hl, de
			jr nc, fs_wr_end
			ld hl, (fs_a2)
			ld de, (fs_cnt)
			add hl, de
			ld a, (hl)
			inc de
			ld (fs_cnt), de
			call fs_putb
			jr fs_wr_lp
fs_wr_end:
			ld hl, (fs_cnt)
			ret

; Seek(h, pos As Long): the next read / write is at byte pos (0 = the start)
fs_seek:
			ld hl, (fs_a1)
			call fs_handle
			ld hl, (fs_a2)			; the Long's address
			ld c, (hl)				; byte 0
			inc hl
			ld e, (hl)				; byte 1
			inc hl
			ld d, (hl)				; byte 2
			inc hl
			ld a, (hl)				; byte 3
			or a
			jr nz, fs_sk_bad
			bit 7, d
			jr nz, fs_sk_bad		; beyond CP/M's 8 MB
			ex de, hl				; HL = bytes 2:1
			ld a, c
			rla						; bit 7 of byte 0
			rl l
			rl h					; HL = the record
			ld a, c
			and 127
			ld c, a					; C = position in the record
			ld a, (ix + FS_BST)
			or a
			jr z, fs_sk_new
			ld a, (ix + FS_RECL)
			cp l
			jr nz, fs_sk_new
			ld a, (ix + FS_RECH)
			cp h
			jr z, fs_sk_pos
fs_sk_new:
			push hl
			push bc
			call fs_flush
			pop bc
			pop hl
			ld (ix + FS_RECL), l
			ld (ix + FS_RECH), h
			ld (ix + FS_BST), 0
fs_sk_pos:
			ld (ix + FS_BPOS), c
			ld hl, 0
			ret
fs_sk_bad:
			ld hl, FS_FAILED
			jp fs_err

; Eof(h): True when nothing more can be read (the end, or ^Z: the end of a text)
fs_eof:
			ld hl, (fs_a1)
			call fs_handle
			ld a, (ix + FS_BPOS)
			cp 128
			call z, fs_next
			ld a, (ix + FS_BST)
			or a
			jr nz, fs_ef_have
			call fs_rdrec
			jr nz, fs_ef_yes
			ld (ix + FS_BST), 1
fs_ef_have:
			call fs_bufpos
			ld a, (hl)
			cp 26
			jr z, fs_ef_yes
			ld hl, 0
			ret
fs_ef_yes:
			ld hl, -1
			ret

; ReadLine(h) As String: up to CR LF / LF (not kept), the end or ^Z; cut at the string's size
fs_readln:
			ld hl, (fs_a1)
			call fs_handle
			ld hl, (fs_res)
			dec hl
			ld a, (hl)
			ld (fs_cap), a			; the result's capacity
			inc hl
			ld (fs_ptr), hl
			ld hl, 0
			ld (fs_cnt), hl
fs_rl_lp:
			call fs_getb
			jr c, fs_rl_end
			cp 26
			jr z, fs_rl_z
			cp 10
			jr z, fs_rl_end
			cp 13
			jr z, fs_rl_lp
			ld c, a
			ld a, (fs_cap)
			ld hl, fs_cnt
			cp (hl)
			jr z, fs_rl_lp			; full: the rest of the line is dropped
			inc (hl)
			ld hl, (fs_ptr)
			ld (hl), c
			inc hl
			ld (fs_ptr), hl
			jr fs_rl_lp
fs_rl_z:
			dec (ix + FS_BPOS)		; leave the ^Z: Eof sees it
fs_rl_end:
			ld hl, (fs_ptr)
			ld (hl), 0
			ret

; WriteLine(h, s): the text and CR LF
fs_writeln:
			ld hl, (fs_a1)
			call fs_handlew
fs_wl_lp:
			ld hl, (fs_a2)
			ld a, (hl)
			or a
			jr z, fs_wl_end
			inc hl
			ld (fs_a2), hl
			call fs_putb
			jr fs_wl_lp
fs_wl_end:
			ld a, 13
			call fs_putb
			ld a, 10
			call fs_putb
			ld hl, 0
			ret

; fs_strout - HL = text (0 ended) into the String result at (fs_res), cut at its size
fs_strout:
			ex de, hl
			ld hl, (fs_res)
			dec hl
			ld b, (hl)			; the capacity
			inc hl
			ex de, hl
fs_so_lp:
			ld a, (hl)
			or a
			jr z, fs_so_end
			ld c, a
			ld a, b
			or a
			jr z, fs_so_end
			ld a, c
			ld (de), a
			inc hl
			inc de
			dec b
			jr fs_so_lp
fs_so_end:
			xor a
			ld (de), a
			ret

; Volumes(): the drives CP/M has used so far (logged in, and the current one): "A,B"
fs_volumes:
			ld c, 24
			call fs_bdos			; HL = login vector
			push hl
			ld c, 25
			call fs_bdos			; A = current drive
			pop hl
			ld b, a
			inc b
			ld de, 1
fs_dv_bit:
			dec b
			jr z, fs_dv_or
			ex de, hl
			add hl, hl
			ex de, hl
			jr fs_dv_bit
fs_dv_or:
			ld a, l
			or e
			ld l, a
			ld a, h
			or d
			ld h, a				; HL = the drives
			ld de, fs_devtxt
			ld c, 'A'
fs_dv_lp:
			srl h
			rr l
			jr nc, fs_dv_next
			ld a, e
			cp low fs_devtxt
			jr z, fs_dv_first
			ld a, ','
			ld (de), a
			inc de
fs_dv_first:
			ld a, c
			ld (de), a
			inc de
fs_dv_next:
			inc c
			ld a, c
			cp 'Q'
			jr nz, fs_dv_lp
			xor a
			ld (de), a
			ld hl, fs_devtxt
			jp fs_strout
fs_devtxt:		ds 33

; CurrentVolume(): the current drive, "A"
fs_curvol:
			ld c, 25
			call fs_bdos
			add a, 'A'
			ld (fs_devtxt), a
			xor a
			ld (fs_devtxt + 1), a
			ld hl, fs_devtxt
			jp fs_strout

; SelectVolume(name): "B" or "B:" - the drive files without a drive letter use.
; CP/M 3 reports a drive that isn't there (NotFound); CP/M 2.2 stops with its BDOS error
fs_selvol:
			ld hl, (fs_a1)
			ld a, (hl)
			call fs_upper
			sub 'A'
			jr c, fs_sl_bad
			cp 16
			jr nc, fs_sl_bad
			ld b, a
			inc hl
			ld a, (hl)
			cp ':'
			jr nz, fs_sl_one
			inc hl
			ld a, (hl)
fs_sl_one:
			or a
			jr nz, fs_sl_bad
			push bc
			ld c, 45
			ld e, #FF			; CP/M 3: errors come back (2.2 ignores this)
			call fs_bdos
			pop bc
			ld e, b
			ld c, 14
			call fs_bdos
			inc a
			ld hl, 0
			ret nz
fs_sl_bad:
			ld hl, FS_NOTFOUND
			ret

; Devices() / CurrentDevice(): CP/M has discs only
fs_devices:
fs_curdev:
			ld hl, fs_n_disc
			jp fs_strout
fs_n_disc:		db "DISC", 0

; SelectDevice(name): "DISC" (any case) - OK; anything else NotFound
fs_select:
			ld hl, (fs_a1)
			ld de, fs_n_disc
fs_sd_lp:
			ld a, (hl)
			call fs_upper
			ld c, a
			ld a, (de)
			cp c
			jr nz, fs_sd_bad
			or a
			jr z, fs_sd_ok
			inc hl
			inc de
			jr fs_sd_lp
fs_sd_ok:
			ld hl, 0
			ret
fs_sd_bad:
			ld hl, FS_NOTFOUND
			ret

; Capability(name) - the class's table at (fs_a2); CPMVERSION (#8000 in the table) asks
; BDOS 12: #22 = CP/M 2.2, #31 = CP/M 3
fs_capab:
			ld hl, (fs_a1)
			ld de, fs_cnt
			ld bc, (fs_a2)
			call ntc_capfind
			ld hl, (fs_cnt)
			ld a, h
			cp #80
			ret nz
			ld a, l
			or a
			ret nz
			ld c, 12
			call fs_bdos
			ld l, a
			ld h, 0
			ret

;## ntc_plat_cmdline ntc_data
; the command line (System.CommandLine): the start code copies CP/M's command
; tail (#80: its length, then the text - CP/M has made it capitals) here first,
; before a disc call or Input can overwrite it
ntc_cmdbuf:		ds 128
; ntc_cmdsave - (call, the start code) #80 into ntc_cmdbuf, 0 ended, without the
; spaces in front
ntc_cmdsave:
			ld hl, #80
			ld b, (hl)
			inc hl
			ld de, ntc_cmdbuf
			ld a, b
			or a
			jr z, ntc_cs_end
ntc_cs_sp:
			ld a, (hl)
			cp ' '
			jr nz, ntc_cs_cp
			inc hl
			djnz ntc_cs_sp
			jr ntc_cs_end
ntc_cs_cp:
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			djnz ntc_cs_cp
ntc_cs_end:
			xor a
			ld (de), a
			ret
; ntc_cmdget - (on the thread) HL = the result String: the command line, cut at
; its capacity
ntc_cmdget:
			dec hl
			ld c, (hl)
			inc hl
			ex de, hl
			ld hl, ntc_cmdbuf
ntc_cg_lp:
			ld a, (hl)
			or a
			jr z, ntc_cg_end
			inc c
			dec c
			jr z, ntc_cg_end
			ld (de), a
			inc hl
			inc de
			dec c
			jr ntc_cg_lp
ntc_cg_end:
			xor a
			ld (de), a
			ret

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: the BDOS (its address is at 6; the CCP below it is free, the program
; ends with a warm boot), or ntc_cpmtop when lower (Graphics on CP/M Plus sets
; it to its copy at GFH_AT). Called on the real stack (call / ret), only by the
; Memory class.
ntc_plat_memtop:
			push de
			ld hl, (ntc_cpmtop)
			ld de, (6)
			or a
			sbc hl, de
			add hl, de
			jr c, ntc_mt1			; ntc_cpmtop lower
			ex de, hl
ntc_mt1:
			pop de
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_m_byr		equ ntc_bss + 0		; 600 bytes
arr_m_byg		equ ntc_bss + 600		; 768 bytes
arr_cybsys_rn		equ ntc_bss + 1368		; 64 bytes
arr_cybsys_b		equ ntc_bss + 1432		; 64 bytes
arr_cybsys_pm		equ ntc_bss + 1496		; 128 bytes
ntc_bss_size	equ 1624
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			ASSERT ntc_free <= #EF00, "the program and its arrays must end below #EF00 (CyborgOS: the slot's stub is #EF00-#FFFF)"
			SAVEAMSDOS "LANG.CYB", ntc_start, ntc_end - ntc_start, ntc_start